pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;
    bool rejectPayments = false;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount <= address(this).balance);
        rejectPayments = true;
        uint beforeBal = address(c).balance;
        uint256 beforeCount;
        try c.depositsCount() returns (uint256 __r) { beforeCount = __r; } catch { return; }
        bool reverted;
        try c.sendMoney(address(this), amount) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && address(c).balance == beforeBal && c.depositsCount() == beforeCount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable { if (rejectPayments) revert(); }
}
